MEAN_DIRECTION = [0.3129, -0.0388, 0.0281, 0.0823, 0.2195, -0.1497, -0.0381, -0.0057, 0.0778, 0.0920, -0.1740, 0.1258, -0.1878, -0.2810, -0.0022, -0.0099, 0.1874, -0.1230, 0.1863, -0.2350, -0.1282, 0.1051, 0.2026, -0.0528, 0.0233, -0.0610, -0.2338, -0.3325, -0.0576, 0.0300, 0.0935, 0.1005, -0.0577, -0.0166, -0.0438, -0.1097, 0.0356, 0.1237, -0.1530, -0.0665, -0.2295, 0.1420, 0.0643, 0.1523, -0.0973, 0.1133, 0.2281, 0.0740]
PERIOD_EDGES = [2.0, 2.5, 3.0, 4.0, 5.0, 6.0, 8.0, 12.0]
BAND_POWER = [0.0390, 0.0645, 0.0888, 0.0883, 0.1027, 0.0739, 0.1162, 0.0882, 0.3383]
N_DIR = (8, 64)


def _period(h, w, device):
    f = (torch.fft.fftfreq(h, device=device)[:, None] ** 2 + torch.fft.fftfreq(w, device=device)[None, :] ** 2).sqrt()
    return 1 / f.clamp_min(1e-9), f > 0


def _unit(x):
    return x / x.pow(2).mean((-2, -1), keepdim=True).sqrt().clamp_min(1e-6)


def gaussian_field(shape, h, w, device):
    """Unit-RMS scalar fields [*shape, h, w] with radial power BAND_POWER[k] on period band k (PERIOD_EDGES)."""
    period, nonzero = _period(h, w, device)
    band = torch.bucketize(period, torch.tensor(PERIOD_EDGES, device=device), right=True)
    amp = torch.tensor(BAND_POWER, device=device)[band].sqrt() * nonzero
    x = torch.randn(*shape, h, w, device=device)
    return _unit(torch.fft.ifft2(torch.fft.fft2(x) * amp).real)


def directions(B, device):
    """[B, N_DIR[1], C] per-sample directions ~ N(0, bank covariance + the unexplained 1 - sum(BANK_VAR) spread
    isotropically), zero beyond each sample's n ~ U{N_DIR}."""
    bank = torch.tensor(BANK, device=device)
    var = torch.tensor(BANK_VAR, device=device)
    C = bank.shape[1]
    n = torch.randint(N_DIR[0], N_DIR[1] + 1, (B,), device=device)
    v = (torch.randn(B, N_DIR[1], len(var), device=device) * var.sqrt()) @ bank
    v = v + torch.randn(B, N_DIR[1], C, device=device) * ((1 - var.sum()).clamp_min(0) / C).sqrt()
    return v * (torch.arange(N_DIR[1], device=device)[None, :, None] < n[:, None, None])


def envelope(mask, coverage, top=(1.5, 4.0)):
    """mask [*S, B, h, w], coverage [B] -> [*S, B, h, w] top-biased smooth support covering ~ coverage of the mask
    weight; one random field per sample, shared over the leading dims S."""
    B, h, w = mask.shape[-3:]
    device = mask.device
    period, nonzero = _period(h, w, device)
    smooth = torch.fft.ifft2(torch.fft.fft2(torch.randn(B, h, w, device=device))
                             * torch.exp(-(4.0 / period) ** 2) * nonzero).real
    row = torch.arange(h, device=device, dtype=torch.float)[:, None] / (h - 1)
    slope = torch.rand(B, device=device) * (top[1] - top[0]) + top[0]
    s = (-slope[:, None, None] * row + _unit(smooth)).flatten(1)
    order = s.argsort(1, descending=True)
    m = mask.flatten(-2)
    cum = torch.gather(m, -1, order.expand_as(m)).cumsum(-1)
    idx = (cum < coverage[:, None] * m.sum(-1, keepdim=True)).sum(-1).clamp_max(h * w - 1)
    thr = torch.gather(torch.gather(s, 1, order).expand_as(m), -1, idx[..., None])
    on = (s >= thr).float().view(-1, 1, h, w)
    return F.avg_pool2d(on, 3, 1, 1, count_include_pad=False)[:, 0].view(mask.shape)


def mosaic_pattern(mask, amplitude, dc, coverage):
    """mask [*S, B, h, w] soft background, amplitude / dc / coverage [B] -> d [*S, B, C, h, w] in per-channel stds;
    one draw per sample, shared over the leading dims S."""
    B, h, w = mask.shape[-3:]
    device = mask.device
    field = torch.einsum('bkc,bkhw->bchw', directions(B, device), gaussian_field((B, N_DIR[1]), h, w, device))
    field = field / field.pow(2).mean((1, 2, 3), keepdim=True).sqrt().clamp_min(1e-6)
    mean = math.sqrt(len(MEAN_DIRECTION)) * torch.tensor(MEAN_DIRECTION, device=device)[:, None, None]
    weight = (mask * envelope(mask, coverage)).unsqueeze(-3)
    return weight * (amplitude[:, None, None, None] * field + dc[:, None, None, None] * mean)
